mapper.sql:
FROM student_users su LEFT JOIN major m ON m.id = su.major_id LEFT JOIN `class` c ON c.id = su.class_id
LEFT JOIN internship_reflection ir ON ir.id = (
    SELECT MAX(latest.id) FROM internship_reflection latest
    WHERE latest.student_id = su.id AND latest.period_number = #{period} AND latest.deleted = 0
)
WHERE su.status = 1

AND su.class_id = #{classId}
AND su.id = #{studentId}

choose.when:
SELECT CAST(dv.id AS CHAR) AS id, dv.name
FROM division dv
WHERE dv.department_id = #{actor.departmentId}
AND dv.id = #{actor.divisionId}
AND 1 = 0
AND dv.id = #{scopeId}
AND dv.name LIKE CONCAT('%', #{scopeName}, '%')
ORDER BY dv.id

mapper.sql:
FROM position p
WHERE p.company_id = #{companyId}
AND p.status = #{status}

FROM student_job_application a
WHERE a.company_id = #{companyId}
AND a.position_id = #{positionId}
AND a.status = #{status}
